/**
 * SLATE — the employers where a character can do their line of work.
 *
 * Generated by `probe/gen-employers.cjs` from research on 2026-09-25
 * (`probe/job-research/<ISO>.json`): for each of the twelve lines of
 * survival work (`content/jobs.ts`), the real employers a person there
 * would work for, with the starting pay each publishes where it publishes
 * one, and the occupation's typical pay from the country's statistics
 * office. Every figure carries its source. Pay is hourly, in hundredths of
 * the country's money.
 */

export interface Employer {
  id: string;
  name: string;
  role: string;
  /** Where it hires: national, or a city or region. */
  where: string;
  /** The starting hourly pay it publishes, and the top of its range. */
  hourlyFrom?: number;
  hourlyTo?: number;
  payNote?: string;
  source: string;
  confidence: 'H' | 'M' | 'L';
}

export interface LineOfWork {
  /** The occupation as the statistics office names it. */
  occupation?: string;
  /** What the occupation typically pays an hour there. */
  typical?: { hourly: number; period: string; source: string };
  employers: readonly Employer[];
}

